-- Combos the way a kru calls them (research: reports/Muay Thai kru heavy bag combos, approved by Josh 2026-10-24).
--
-- Naming: a kick with no side named is the right leg (Low Kick, Body Kick, Head Kick).
-- Left kicks say how: Switch Kick when the feet swap, Left Kick when they do not
-- (step through), Inside Low Kick for the lead leg to the inside thigh. Teeps name
-- the leg. Knees and elbows say Left/Lead or Rear.
--
-- Combo rows are updated by id (text, tips, cue, video); mastery, favourites and
-- unlocks are not touched. 19 new combos (INSERT OR IGNORE): head kicks only in
-- Mastery; knee and elbow ones open like the others, behind their Settings switch.
-- Axe Kick and Spinning Back Kick are removed (combos and techniques), only when no
-- logged round or rating uses them. "Left Kick" moves from the Switch Kick to a new
-- Left Kick technique; "Step In" is no longer read as a Step Knee.

-- ─── combos ───
UPDATE combos SET text = 'Body Kick', form_tips = 'Step out, turn on the ball of the standing foot. | Shin lands, not the foot. | Drill: 50 right kicks, moving round the bag (Fagan).' WHERE id = 'combo-f09';
UPDATE combos SET text = 'Jab → Body Kick', cue = 'JAB, THEN KICK', form_tips = 'The jab measures; the right kick comes straight off it. | Belly button faces the bag at impact.' WHERE id = 'combo-w01';
UPDATE combos SET text = 'Jab → Jab → Lead Teep' WHERE id = 'combo-w05';
UPDATE combos SET text = 'Lead Teep → Jab → Cross' WHERE id = 'combo-w07';
UPDATE combos SET text = 'Jab → Cross → Left Knee', cue = 'CROSS LOADS THE KNEE', form_tips = 'The cross loads your left side. | Step in and drive the left knee up and through.' WHERE id = 'combo-w10';
UPDATE combos SET text = 'Lead Teep → Step In → Rear Knee' WHERE id = 'combo-w11';
UPDATE combos SET cue = 'STEP THROUGH', form_tips = 'Step through with the right foot; do not switch. | Kick the body as the overhand turns you. | If it misses, the kick follows anyway.', tiktok_url = 'https://www.tiktok.com/@trainor103/video/7143247780805479685', form_video_url = 'https://www.youtube.com/watch?v=WUoEDuMQhOg', video_source = 'Sean "Muay Thai Guy" Fagan', video_title = 'Bang Muay Thai Combo - Jab, Knee, Overhand, Kick', video_length = '1:29', video_start_sec = NULL, video_status = 'live' WHERE id = 'combo-w12';
UPDATE combos SET text = 'Lead Teep → Low Kick' WHERE id = 'combo-w15';
UPDATE combos SET text = 'Cross → Hook → Cross → Switch Kick', form_tips = 'Three punches, then switch and kick. | Do not plant flat between strikes.', form_video_url = 'https://www.youtube.com/watch?v=yDil9i8g9bM', video_source = 'EvermoreMuayThai', video_title = 'Basic Combo - Jab-Uppercut-Hook-Cross-Switch Kick/Knee', video_length = '4:16', video_start_sec = NULL, video_status = 'live' WHERE id = 'combo-fl01';
UPDATE combos SET text = 'Double Jab → Cross → Body Kick' WHERE id = 'combo-fl02';
UPDATE combos SET text = 'Inside Low Kick → Cross → Hook → Low Kick', form_tips = 'Inside kick and step slightly out. | The angle opens the line for the cross. | The hook loads the right low kick.', alt_video_url = 'https://www.youtube.com/watch?v=VnGeTJ6yuyI', alt_video_source = 'Evolve Mixed Martial Arts', alt_video_status = 'live', form_video_url = 'https://www.youtube.com/watch?v=9Z8dcItvJw8', video_source = 'Sean "Muay Thai Guy" Fagan', video_title = 'Muay Thai Combination - Low Kick, Cross, Hook, Low Kick', video_length = '1:50', video_start_sec = NULL, video_status = 'live' WHERE id = 'combo-fl03';
UPDATE combos SET text = 'Jab → Cross → Lead Hook Body → Body Kick' WHERE id = 'combo-fl04';
UPDATE combos SET text = 'Low Kick → Jab → Cross → Inside Low Kick', form_tips = 'Low kick, hands back up, then the punches. | Finish with a quick lead-leg kick to the inside of the thigh.', form_video_url = 'https://www.youtube.com/watch?v=8GaYtf8hmyg', video_source = 'Gabriel Varga', video_title = 'Dutch Kickboxing | 5 Must Know Combos & Why They Work', video_length = '8:12', video_start_sec = NULL, video_status = 'live' WHERE id = 'combo-fl05';
UPDATE combos SET text = 'Switch Kick → Jab → Cross → Body Kick' WHERE id = 'combo-fl07';
UPDATE combos SET text = 'Feint Jab → Cross → Switch Kick → Step Out', form_tips = 'Commit the shoulder on the feint. | Switch as the cross comes back. | Step out after the kick.' WHERE id = 'combo-d01';
UPDATE combos SET text = 'Jab → Feint Lead Teep → Cross → Hook → Reset' WHERE id = 'combo-d02';
UPDATE combos SET text = 'Feint Low Kick → Cross → Hook → Body Kick', form_tips = 'The low-kick feint pulls their guard down. | Punch high, then the right kick to the body.' WHERE id = 'combo-d03';
UPDATE combos SET text = 'Jab → Check → Cross → Hook → Body Kick' WHERE id = 'combo-d04';
UPDATE combos SET text = 'Lead Teep → Step Back → Cross → Hook → Low Kick' WHERE id = 'combo-d06';
UPDATE combos SET text = 'Feint Lead Teep → Step In → Rear Knee → Jab → Cross' WHERE id = 'combo-d08';
UPDATE combos SET text = 'Lead Teep → Fake Teep → Step Knee' WHERE id = 'combo-d10';
UPDATE combos SET text = 'Double Jab → Feint Cross → Body Kick → Reset' WHERE id = 'combo-m01';
UPDATE combos SET text = 'Jab → Cross → Hook → Check → Lead Teep' WHERE id = 'combo-m02';
UPDATE combos SET text = 'Jab → Cross → Feint Hook → Low Kick → Exit' WHERE id = 'combo-m03';
UPDATE combos SET text = 'Feint Lead Teep → Cross → Hook → Cross → Reset' WHERE id = 'combo-m04';
UPDATE combos SET text = 'Parry → Cross → Lead Hook → Body Kick' WHERE id = 'combo-m05';
UPDATE combos SET text = 'Jab → Cross → Hook → Rear Elbow → Left Knee → Reset', form_tips = 'The hook turns you; the rear elbow comes over the top. | Then the knee from the other side. | Exit clean.' WHERE id = 'combo-m07';
UPDATE combos SET cue = 'SELL THE TEEP', form_tips = 'Start it like a lead teep. | Turn the knee over and whip it high.' WHERE id = 'combo-m08';
