DELETE FROM combos WHERE id IN ('combo-w17', 'combo-m09') AND id NOT IN (SELECT combo_id FROM bag_work_round_combos) AND id NOT IN (SELECT combo_id FROM combo_performance);

-- ─── techniques ───
UPDATE techniques SET aliases = '["Jab", "Double Jab", "Jab x 3", "Body Jab"]' WHERE id = 'tech-jab';
UPDATE techniques SET aliases = '["Hook", "Lead Hook", "Lead Hook Body", "Step Back Hook"]' WHERE id = 'tech-lead-hook';
UPDATE techniques SET coach_hint = 'Followed by a left kick (step through, no switch) or a hook.' WHERE id = 'tech-overhand';
UPDATE techniques SET name = 'Lead Teep', aliases = '["Lead Teep", "Teep", "Fake Teep"]', coach_hint = 'Your range finder: the quick, everyday teep. Use it to stop them coming in.' WHERE id = 'tech-teep';
UPDATE techniques SET name = 'Body Kick', aliases = '["Body Kick"]', coach_hint = 'Your main kick: the right kick to the body. After a hook or a jab, this is the kick.' WHERE id = 'tech-roundhouse';
UPDATE techniques SET aliases = '["Switch Kick"]', coach_hint = 'The feet swap, then the left leg kicks from the back. After a cross, this is the left kick.' WHERE id = 'tech-switch-kick';
UPDATE techniques SET aliases = '["Low Kick"]', coach_hint = 'Chops the leg. After a hook, the right leg is loaded for it.' WHERE id = 'tech-low-kick';
UPDATE techniques SET aliases = '["Inside Low Kick"]', coach_hint = 'A range finder like the jab. Lead leg, no switch.' WHERE id = 'tech-inside-low-kick';
UPDATE techniques SET cue = 'Start it like a lead teep, then turn the knee over and whip the shin up to the head or body.', tips = 'The teep start is the feint; sell it.' WHERE id = 'tech-question-mark';
UPDATE techniques SET aliases = '["Step Knee"]' WHERE id = 'tech-step-knee';
UPDATE techniques SET aliases = '["Feint", "Feint Jab", "Feint Cross", "Feint Hook", "Feint Low Kick", "Feint Lead Teep", "Feint Switch Kick"]' WHERE id = 'tech-feint';
INSERT OR IGNORE INTO techniques (id, name, kind, aliases, sort, created_at, cue, tips, coach_hint, form_video_url, video_source, video_title, video_length, video_start_sec, video_status) VALUES ('tech-left-kick', 'Left Kick', 'Kick', '["Left Kick"]', 23, 1792800000, 'Step through with the right foot, no switch, and kick with the left leg. The overhand turns you into it.', 'Step, do not hop. | Kick the body. | Back to orthodox after.', 'Not a switch kick: the feet never swap. After an overhand, this is the left kick.', 'https://www.youtube.com/watch?v=WUoEDuMQhOg', 'Sean "Muay Thai Guy" Fagan', 'Bang Muay Thai Combo - Jab, Knee, Overhand, Kick', '1:29', NULL, 'live');
INSERT OR IGNORE INTO techniques (id, name, kind, aliases, sort, created_at, cue, tips, coach_hint, form_video_url, video_source, video_title, video_length, video_start_sec, video_status) VALUES ('tech-head-kick', 'Head Kick', 'Kick', '["Head Kick"]', 24, 1792800000, 'The right kick, turned over high. Set it up with body work so their elbows drop.', 'Height comes from the hip, not from leaning back. | Body work first. | Only once the hips are ready.', 'Mastery tier. The coach holds it back until the rest is solid.', 'https://www.youtube.com/watch?v=a81edkZAudY', 'Gabriel Varga', '6 Ways To Setup Your Head Kicks', '9:14', NULL, 'live');
INSERT OR IGNORE INTO techniques (id, name, kind, aliases, sort, created_at, cue, tips, coach_hint, form_video_url, video_source, video_title, video_length, video_start_sec, video_status) VALUES ('tech-rear-teep', 'Rear Teep', 'Kick', '["Rear Teep"]', 25, 1792800000, 'Right leg teep: lift the knee, drive the hip forward and push them back. The power teep.', 'Set it up with a kick or a step back. | Belly or chest. | To stop them coming in, use the lead teep instead.', 'The big shove that knocks them off balance.', 'https://www.youtube.com/watch?v=uMkxXP3ZMGI', 'Pro Striking', 'Learn Muay Thai''s Key to Control - The Teep (Pro Striking Breakdown)', '8:53', NULL, 'live');
INSERT OR IGNORE INTO techniques (id, name, kind, aliases, sort, created_at, cue, tips, coach_hint, form_video_url, video_source, video_title, video_length, video_start_sec, video_status) VALUES ('tech-left-knee', 'Left Knee', 'Knee', '["Left Knee"]', 26, 1792800000, 'Step in and drive the lead knee up and through. The cross loads it.', 'Knee goes forward, not just up. | Rise onto the ball of the standing foot.', 'After a cross, this is the knee.', 'https://www.youtube.com/watch?v=0DU7x4iKNUE', 'TAG Muay Thai', 'Clinch Entry - Jab Cross Knee with Jalill Barnes', '0:43', NULL, 'live');
INSERT OR IGNORE INTO techniques (id, name, kind, aliases, sort, created_at, cue, tips, coach_hint, form_video_url, video_source, video_title, video_length, video_start_sec, video_status) VALUES ('tech-switch-knee', 'Switch Knee', 'Knee', '["Switch Knee"]', 27, 1792800000, 'Switch the feet, then drive the left knee from the back.', 'Small, fast switch. | Hips forward into the knee.', 'Out with the switch kick, in with the switch knee.', 'https://www.youtube.com/watch?v=9E3vjGFlnUU', 'Sean "Muay Thai Guy" Fagan', 'Muay Thai Heavy Bag Drill: Switch Kick to Switch Knee', '2:08', NULL, 'live');
INSERT OR IGNORE INTO techniques (id, name, kind, aliases, sort, created_at, cue, tips, coach_hint, form_video_url, video_source, video_title, video_length, video_start_sec, video_status) VALUES ('tech-rear-elbow', 'Rear Elbow', 'Elbow', '["Rear Elbow"]', 28, 1792800000, 'Right elbow off the turn back from a hook or a knee. Short, sharp, over the top.', 'Open hand, loose shoulder. | Other hand stays up.', 'After a lead hook or a left knee, this is the elbow.', 'https://www.youtube.com/watch?v=Dv4T9JH_N9M', 'Liam Harrison', 'My Favourite Ways To Land The Elbow (w/ Fight Footage)', '9:21', NULL, 'live');
DELETE FROM techniques WHERE id IN ('tech-axe-kick', 'tech-spinning-back-kick');
